import{_ as i,o as n,c as a,ag as l}from"./chunks/framework.PVHj0As1.js";const g=JSON.parse('{"title":"32-Option 使用","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/32-Option 使用/32-Option 使用.md","filePath":"仓颉入门到实战/32-Option 使用/32-Option 使用.md","lastUpdated":1735725812000,"__rawMarkdown":"# 32-Option 使用\\n\\n## 前言\\n\\n因为 Option 类型可以同时表示有值和无值两种状态，而无值在某些情况下也可以理解为一种错误，所以 Option 类型也可以用作错\\n\\n误处理。\\n\\n## 示例\\n\\n```javascript\\nfunc getString(p: ?Int64): String {\\n    match (p) {\\n        case Some(x) => \\"${x}\\"\\n        case None => \\"none\\"\\n    }\\n}\\n\\nmain() {\\n    let a = Some(1)\\n    let b: ?Int64 = None\\n    let r1 = getString(a)\\n    let r2 = getString(b)\\n    println(r1) // 1 \\n    println(r2) // \\"none\\"\\n}\\n```\\n\\n## Option 常用场景\\n\\n因为 `Option` 是一种非常常用的类型，所以仓颉为其提供了多种解构方式，以方便 `Option` 类型的使用。具体包括：模式匹配、`错误处理` 函数、`coalescing` 操作符（`??`），以及问号操作符（`?`）\\n\\n## 模式匹配\\n\\n因为 Option 类型是一种 enum 类型，所以可以使用上文提到的 enum 的模式匹配来实现对 `Option` 值的解构。例如，下例中函数 \\n\\n`getString` 接受一个 `?Int64` 类型的参数，当参数是 `Some` 值时，返回其中数值的字符串表示，当参数是 `None` 值\\n\\n时，返回字符串 `\\"none\\"`\\n\\n```javascript\\nfunc getString(p: ?Int64): String{\\n    match (p) {\\n        case Some(x) => \\"${x}\\"\\n        case None => \\"none\\"\\n    }\\n}\\nmain() {\\n    let a = Some(1)\\n    let b: ?Int64 = None\\n    let r1 = getString(a)\\n    let r2 = getString(b)\\n    println(r1)\\n    println(r2)\\n}\\n```\\n\\n\\n\\n## getOrThrow 函数\\n\\n`getOrThrow` 是 Option包装后的类型的一个函数，它有以下特点，比如 `a.getOrThrow()`\\n\\n1. 如果a是属于`Some` 类型，那么`a.getOrThrow ()`返回数据本身\\n2. 如果a是属于`None`类型，那么`a.getOrThrow ()`抛出异常\\n\\n```javascript\\nmain() {\\n    let a = Some(1)\\n    let b: ?Int64 = None\\n    let r1 = a.getOrThrow()\\n    println(r1)\\n    try {\\n        let r2 = b.getOrThrow()\\n    } catch (e: NoneValueException) {\\n        println(\\"b is None\\")\\n    }\\n}\\n```\\n\\n## coalescing  ??\\n\\n`coalescing  `   `/ˌkəʊəˈlesɪŋ/`  联合合并的意思。对于表达式  `a??b`，如果\\n\\n1. **a**  属于 `Some` 类型 ， 返回**a**本身\\n2. **a**属于`None`类型，返回 **b**\\n\\n```javascript\\n\\nmain() {\\n    let a = Some(1)\\n    let b: ?Int64 = None\\n    let r1: Int64 = a ?? 0 //  r1 = 1 \\n    let r2: Int64 = b ?? 0 //   r2 = 0\\n    println(r1) // 1 \\n    println(r2) // 0 \\n}\\n```\\n\\n## 问号操作符 ?\\n\\n问号操作符 `？` 可以理解为是个可选的意思。因为使用了`Option`包装正常的数据，那么它就有可能会是`None`，所以在使用了`Option`包装的数据，想要继续用它内层的属性时，就需要用 `?`\\n\\n```javascript\\nstruct R {\\n    public var a: Int64\\n    public init(a: Int64) {\\n        this.a = a\\n    }\\n}\\n\\nmain() {\\n    let r = R(100)\\n    let x = Some(r) // 等于使用了 Option.Some 来包装了\\n    let y = Option<R>.None // 等于使用了 Option.Some 来包装了\\n    let r1 = x?.a // r1 = Option<Int64>.Some(100)\\n    let r2 = y?.a // r2 = Option<Int64>.None\\n    println(r1) // Some(100)\\n    println(r2) // None\\n}\\n```\\n\\n"}'),p={name:"仓颉入门到实战/32-Option 使用/32-Option 使用.md"};function t(e,s,h,k,r,E){return n(),a("div",null,[...s[0]||(s[0]=[l("",24)])])}const o=i(p,[["render",t]]);export{g as __pageData,o as default};
